-- Fields generated by Better Auth 1.7.7's official Admin plugin schema.
ALTER TABLE "user"
  ADD COLUMN "role" TEXT,
  ADD COLUMN "banned" BOOLEAN DEFAULT false,
  ADD COLUMN "banReason" TEXT,
  ADD COLUMN "banExpires" TIMESTAMP(3);

ALTER TABLE "session" ADD COLUMN "impersonatedBy" TEXT;

-- Preserve existing administrators; Better Auth roles now own authorization.
UPDATE "user"
SET "role" = CASE WHEN "isSuperuser" THEN 'admin' ELSE 'user' END;
